"""The consumer publishes artifacts generated by its locked installed API."""
import json
from pathlib import Path

from scripts.export_mobile_contracts import export
from techflex_cloud_foundation.server.contract_export import build_openapi, build_vectors


def test_consumer_exports_match_installed_generator(tmp_path):
    export(tmp_path)
    root = Path(__file__).resolve().parents[2] / "cloud/contracts/mobile"
    for name, expected in (("openapi.json", build_openapi()), ("vectors.json", build_vectors())):
        assert json.loads((tmp_path / name).read_text(encoding="utf-8")) == expected
        assert (root / name).read_bytes() == (tmp_path / name).read_bytes()
